pub fn choose_num(x: i8, y: i8) -> i8 {
    // If the lower bound is greater than the upper bound, no valid interval.
    if x > y {
        return -1;
    }

    // Find the largest even number <= y.
    let largest_even = if y % 2 == 0 { y } else { y - 1 };

    // If that even number is still below the lower bound, no even in the interval.
    if largest_even < x {
        -1
    } else {
        largest_even
    }
}

